const chunks = splitText(doc.content, { size: 500, overlap: 50 });
for (const chunk of chunks) {
  const vector = await embed(chunk.text);
  await vectorDb.insert({ vector, text: chunk.text, source: doc.name });
}

const queryVector = await embed(question);
const results = await vectorDb.search(queryVector, { topK: 3 });
const context = results.map(r => r.text).join('
---
');
const prompt = `Answer using only this context:
${context}

Question: ${question}`;

const answer = await callLLM(prompt);
const sources = results.map(r => ({ title: r.source, url: r.url }));
return { answer, sources };

